cases.admin_early_return:
def access(current_user, item):
    if current_user.is_superuser:
        return item
    if item.owner_id != current_user.id:
        raise Denied(status_code=403)
    return item

cases.masked_404:
def access(current_user, item):
    if item.owner_id != current_user.id:
        raise Denied(status_code=404)
    return item

cases.helper_guard:
def access(current_user, item):
    require_owner(current_user, item)
    return item

cases.assert_guard:
def access(current_user, item):
    assert item.owner_id == current_user.id
    return item

cases.unknown_tenant:
def access(current_user, item):
    if item.tenant_id != current_user.tenant_id:
        raise Denied(status_code=403)
    return item

cases.alias_owner:
def access(current_user, item):
    caller = current_user
    if item.owner_id != caller.id:
        raise Denied(status_code=403)
    return item

cases.nested_guard:
def access(current_user, item):
    if not current_user.is_superuser:
        if item.owner_id != current_user.id:
            raise Denied(status_code=403)
    return item
